script:
// Mercury: the custom "Delivered" Task status.
//
// HISTORY - do not "restore" the old behaviour without reading this.
// This script used to REMOVE "Delivered" from the dropdown unless the task's
// company had opted in. That was abandoned because it is unreliable:
// frm.get_field("status").df IS the doctype meta object, not a copy, so writing
// field.df.options mutates meta for the whole session. On a new Task, refresh runs
// before a project is chosen, the option was stripped from meta, and selecting the
// project afterwards could not bring it back. Frappe also caches doctype metadata
// and client scripts in localStorage, so a stale copy survives a hard refresh and
// the behaviour differs between browsers.
//
// Now it only ever ADDS the option, never removes it - so there is no shared state
// to corrupt and nothing to go stale.
//
// THE GATE IS SERVER-SIDE: mercury/task_status.py validate(), wired through
// doc_events. A task on a company that has not ticked "Allow Delivered Task Status"
// is REFUSED on save, whether it comes from this form, the REST API or a Data
// Import. Someone on another company can see the option and will be told no.

const MERCURY_DELIVERED = "Delivered";

frappe.ui.form.on("Task", {
    refresh(frm) {
        try {
            const field = frm.get_field("status");
            if (!field) return;
            const opts = (field.df.options || "").split("\n");
            if (opts.includes(MERCURY_DELIVERED)) return;
            const at = opts.indexOf("Completed");
            if (at >= 0) opts.splice(at + 1, 0, MERCURY_DELIVERED);
            else opts.push(MERCURY_DELIVERED);
            field.df.options = opts.join("\n");
            frm.refresh_field("status");
        } catch (e) {
            console.error("Mercury delivered status:", e);
        }
    },
});

// RTM approval workflow as a compact stepper inside the PAGE HEAD, between the
// document title and the action buttons.
// Draft -> Under Customer Review -> RTM Approved. "Revision Requested" is a BRANCH
// that loops back to review, so it is not drawn as a fourth step - the bar holds at
// step 2 and turns amber.

frappe.ui.form.on("Sales Order", {
    onload_post_render(frm) { queue_rtm_stepper(frm); },
    refresh(frm) { queue_rtm_stepper(frm); },
});

function queue_rtm_stepper(frm) {
    // the page head is redrawn after refresh, so wait for it to settle
    setTimeout(() => {
        try { render_rtm_stepper(frm); } catch (e) { console.error("RTM stepper:", e); }
    }, 200);
}

function render_rtm_stepper(frm) {
    $(".mercury-rtm-stepper").remove();

    const state = frm.doc.workflow_state;
    if (!state) return;

    const MAIN = ["Draft", "Submittal Under Customer Review", "RTM Approved"];
    const SHORT = { "Draft": "Draft",
                    "Submittal Under Customer Review": "Under Customer Review",
                    "RTM Approved": "RTM Approved" };
    const revising = state === "Revision Requested";
    let current = MAIN.indexOf(state);
    if (revising) current = 1;
    if (current < 0) return;

    let parts = [];
    MAIN.forEach((s, i) => {
        if (i) parts.push('<span class="mrs-line"></span>');
        const done = i < current;
        const active = i === current;
        const cls = done ? "done" : active ? (revising ? "warn" : "active") : "todo";
        const mark = done ? "&#10003;" : (i + 1);
        parts.push('<span class="mrs-step ' + cls + '">' +
                     '<span class="mrs-dot">' + mark + "</span>" +
                     '<span class="mrs-label">' + SHORT[s] + "</span>" +
                   "</span>");
    });
    if (revising) {
        parts.push('<span class="mrs-branch">&#8630; Revision Requested</span>');
    }

    const html =
      '<div class="mercury-rtm-stepper">' +
      "<style>" +
      ".mercury-rtm-stepper{display:inline-flex;align-items:center;gap:7px;" +
        "white-space:nowrap;vertical-align:middle;margin-left:auto;margin-right:12px}" +
      ".mercury-rtm-stepper .mrs-step{display:inline-flex;align-items:center;gap:6px}" +
      ".mercury-rtm-stepper .mrs-dot{display:inline-block;width:20px;height:20px;" +
        "line-height:16px;text-align:center;border-radius:50%;font-size:11px;font-weight:600;" +
        "background:var(--control-bg,#f4f5f6);color:#6c757d;border:2px solid #aab2bb}" +
      ".mercury-rtm-stepper .mrs-label{font-size:12px;color:#6c757d}" +
      // a real line with an arrowhead, not a table cell
      ".mercury-rtm-stepper .mrs-line{display:inline-block;position:relative;width:29px;" +
        "height:2px;background:#8a949e;margin:0 4px}" +
      ".mercury-rtm-stepper .mrs-line:after{content:\"\";position:absolute;right:-1px;top:-3px;" +
        "border-left:7px solid #8a949e;border-top:4px solid transparent;" +
        "border-bottom:4px solid transparent}" +
      ".mercury-rtm-stepper .done .mrs-dot{background:#2e7d32;border-color:#2e7d32;color:#fff}" +
      ".mercury-rtm-stepper .done .mrs-label{color:var(--text-color)}" +
      ".mercury-rtm-stepper .active .mrs-dot{background:#1f4e79;border-color:#1f4e79;color:#fff}" +
      ".mercury-rtm-stepper .active .mrs-label{color:var(--text-color);font-weight:600}" +
      ".mercury-rtm-stepper .warn .mrs-dot{background:#b26a00;border-color:#b26a00;color:#fff}" +
      ".mercury-rtm-stepper .warn .mrs-label{color:#b26a00;font-weight:600}" +
      ".mercury-rtm-stepper .mrs-branch{font-size:11px;font-weight:600;color:#b26a00;" +
        "background:#fff6e5;border:1px solid #e6c98a;border-radius:12px;padding:2px 9px}" +
      "</style>" + parts.join("") + "</div>";

    // sit in the page head, just after the title / status pill
    const $head = $(frm.page.wrapper).find(".page-head");

    // right-hand end of the header: immediately before the action buttons.
    // margin-left:auto does the pushing when that row is a flex container.
    const $actions = $head.find(".page-actions").first();
    if ($actions.length) { $actions.before(html); return; }

    const fallbacks = [
        $head.find(".title-area").first(),
        $head.find(".page-title").first(),
    ];
    for (const $a of fallbacks) {
        if ($a && $a.length) { $a.append(html); return; }
    }
    console.warn("RTM stepper: no page-head anchor found");
}
